var C = ARISTO.colors;
var nIn = document.getElementById('n');
var labelBtn = document.getElementById('labelToggle');
var showLabel = true;

var baseNum = 1, baseDen = 2;

var pizza = ARISTO.canvas(document.getElementById('pizza'), function (ctx, w, h) {
  var n = +nIn.value;
  var den = baseDen * n;
  var num = baseNum * n;
  var cx = w / 2, cy = h / 2 - (showLabel ? 10 : 0);
  var r = Math.min(w, h) * 0.38;

  // crust
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fillStyle = C.surface;
  ctx.fill();

  // shaded slices
  var sliceAngle = (Math.PI * 2) / den;
  var start = -Math.PI / 2;
  for (var i = 0; i < den; i++) {
    var a0 = start + i * sliceAngle;
    var a1 = a0 + sliceAngle;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.arc(cx, cy, r, a0, a1);
    ctx.closePath();
    ctx.fillStyle = (i < num) ? C.accentText : C.sunk;
    ctx.fill();
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = C.line;
    ctx.stroke();
  }

  // outer crust ring
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.lineWidth = 3;
  ctx.strokeStyle = C.muted;
  ctx.stroke();

  if (showLabel) {
    ctx.fillStyle = C.ink;
    ctx.font = '600 16px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(num + '/' + den, cx, cy + r + 24);
    ctx.textAlign = 'left';
  }
}, 0.58);

function update() {
  var n = +nIn.value;
  var den = baseDen * n;
  var num = baseNum * n;
  document.getElementById('nv').textContent = String(n);
  document.getElementById('eq').textContent = num + '/' + den + ' of the pizza (same as 1/2)';
  pizza.redraw();
}

labelBtn.addEventListener('click', function () {
  showLabel = !showLabel;
  labelBtn.setAttribute('aria-pressed', String(showLabel));
  labelBtn.textContent = showLabel ? 'On' : 'Off';
  pizza.redraw();
});

nIn.addEventListener('input', update);
update();
